const sofaShowcase = {
  meta,
  replacesProductIds,
  products
};
function createRuntimeProducts(baseProducts = [], showcase = {}) {
  const replaced = new Set((showcase.replacesProductIds || []).map(String));
  const supplemental = showcase.products || [];
  const products2 = [];
  for (const product of baseProducts) {
    if (replaced.has(String(product.id)))
      continue;
    products2.push(product);
    if (product.title === "简牍沙发")
      products2.push(...supplemental);
  }
  return products2.map((product) => mapRuntimeAssets(product));
}
